CREATE TABLE IF NOT EXISTS clubs(slug TEXT PRIMARY KEY,name TEXT NOT NULL,division TEXT NOT NULL CHECK(division IN('East','West','Representative')),active INTEGER NOT NULL DEFAULT 1,sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('contributor','admin')),club TEXT REFERENCES clubs(slug),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY,club TEXT NOT NULL REFERENCES clubs(slug),type TEXT NOT NULL,title TEXT NOT NULL,caption TEXT NOT NULL DEFAULT '',year TEXT NOT NULL DEFAULT '',people TEXT NOT NULL DEFAULT '',event TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT '',contact TEXT NOT NULL DEFAULT '',permission INTEGER NOT NULL CHECK(permission=1),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','corrections_requested','declined','removed')),reviewer_note TEXT NOT NULL DEFAULT '',submitted_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TEXT,reviewed_by INTEGER REFERENCES users(id));
CREATE INDEX IF NOT EXISTS items_status_club ON items(status,club);
CREATE TABLE IF NOT EXISTS nominations(id INTEGER PRIMARY KEY,category TEXT NOT NULL CHECK(category IN('remarkables','legends','tributes')),nominee TEXT NOT NULL,clubs TEXT NOT NULL DEFAULT '',roles TEXT NOT NULL DEFAULT '',years TEXT NOT NULL DEFAULT '',story TEXT NOT NULL,nominator_name TEXT NOT NULL,nominator_contact TEXT NOT NULL,sources TEXT NOT NULL DEFAULT '',family_consulted INTEGER NOT NULL DEFAULT 0,acknowledged INTEGER NOT NULL CHECK(acknowledged=1),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','declined')),reviewer_note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,item_id INTEGER REFERENCES items(id) ON DELETE CASCADE,nomination_id INTEGER REFERENCES nominations(id) ON DELETE CASCADE,path TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,original_name TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY,item_id INTEGER NOT NULL REFERENCES items(id) ON DELETE CASCADE,message TEXT NOT NULL,contact TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','resolved')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS entries(id INTEGER PRIMARY KEY,club TEXT NOT NULL REFERENCES clubs(slug),kind TEXT NOT NULL CHECK(kind IN('player','team')),name TEXT NOT NULL,role TEXT NOT NULL DEFAULT '',years TEXT NOT NULL DEFAULT '',bio TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('reunion','news')),title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,user_id INTEGER,action TEXT NOT NULL,target TEXT NOT NULL DEFAULT '',at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
